/**
 * Bakes four Wikidata snapshots into the repo before `astro build`, so the
 * country, airport, language and city tools ship real reference data without
 * any of them making a runtime request to Wikidata.
 *
 * Companion to scripts/prepare-models.mjs: same shape, same idea, different
 * payload. Fetch once, cache the raw responses, write reproducible outputs,
 * print counts, never refetch on a rebuild.
 *
 * Outputs (all gitignored, all regenerated by this script):
 *   src/tools/_generated/wikidata-countries.ts   COUNTRIES: Country[]
 *   src/tools/_generated/wikidata-airports.ts    AIRPORTS: Airport[]
 *   src/tools/_generated/wikidata-languages.ts   LANGUAGES, SCRIPTS
 *   public/data/wikidata-cities.sqlite           cities + countries tables
 *
 * Usage:
 *   node scripts/prepare-wikidata.mjs
 *   node scripts/prepare-wikidata.mjs --only countries
 *   node scripts/prepare-wikidata.mjs --refresh      ignore the response cache
 *   node scripts/prepare-wikidata.mjs --offline      cache only, never fetch
 *
 * How the queries are written, and why:
 *
 *  - One dataset is assembled from several small focused queries rather than
 *    one wide query with a dozen OPTIONAL blocks. Wide queries on WDQS either
 *    time out or return a cartesian product big enough to be its own problem.
 *    Small queries are individually fast, individually cacheable and, when one
 *    of them breaks, individually debuggable.
 *  - Multi-valued properties come back as several rows. Every field is
 *    collected into a Set and then reduced with a total order (lexicographic
 *    minimum for strings, maximum for "latest wins" numbers). SPARQL only
 *    orders subjects, not the rows inside a subject, so without that the
 *    generated files would churn between runs on identical data.
 *  - Anything expensive is sharded (airports by IATA prefix, cities by
 *    population band) and any shard WDQS refuses is subdivided automatically.
 *    See sparqlSharded in scripts/lib/wikidata-sparql.mjs.
 *
 * Data license: Wikidata is CC0 1.0. Attribution is not required but the
 * generated modules carry a WIKIDATA_META.license field anyway.
 *
 * No dependencies beyond node builtins, except the sql.js fallback that only
 * runs when node:sqlite is unavailable.
 */
import { existsSync, mkdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { rowsLiteral, writeGeneratedModule } from "./lib/wikidata-emit.mjs";
import {
  OfflineCacheMissError,
  pruneCache,
  sparql,
  sparqlSharded,
  stats,
} from "./lib/wikidata-sparql.mjs";

const root = fileURLToPath(new URL("../", import.meta.url));
const generatedDir = join(root, "src", "tools", "_generated");
const publicDataDir = join(root, "public", "data");

const IGNORE_ALL = "*\n!.gitignore\n";

// ---------------------------------------------------------------------------
// Arguments
// ---------------------------------------------------------------------------

const argv = process.argv.slice(2);
const DATASETS = ["countries", "airports", "languages", "cities"];
let only = null;
let refresh = false;
let offline = false;

for (let i = 0; i < argv.length; i += 1) {
  const arg = argv[i];
  if (arg === "--refresh") refresh = true;
  else if (arg === "--offline") offline = true;
  else if (arg === "--only") {
    only = (argv[i + 1] ?? "")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    i += 1;
  } else if (arg.startsWith("--only=")) {
    only = arg
      .slice("--only=".length)
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
  } else {
    fail(`unknown argument ${arg}. Expected --only <dataset>, --refresh or --offline.`);
  }
}
if (only) {
  const bad = only.filter((name) => !DATASETS.includes(name));
  if (bad.length) fail(`--only got ${bad.join(", ")}. Valid: ${DATASETS.join(", ")}.`);
}
const wanted = new Set(only ?? DATASETS);
const queryOptions = { refresh, offline };

function fail(message) {
  console.error(`prepare-wikidata: ${message}`);
  process.exit(1);
}

function log(message) {
  console.log(`prepare-wikidata: ${message}`);
}

// ---------------------------------------------------------------------------
// Shared value helpers
//
// Every one of these is total and deterministic. Wikidata hands back the same
// facts in an arbitrary row order, so "first row wins" is not a rule, it is a
// coin flip that would rewrite the generated files on every run.
// ---------------------------------------------------------------------------

/** Entity id from a Wikidata entity URI, or null for anything else. */
function qidOf(uri) {
  const match = /\/(Q\d+)$/.exec(uri ?? "");
  return match ? match[1] : null;
}

/** Binding value, or undefined when the variable was unbound in this row. */
function v(row, name) {
  const value = row[name]?.value;
  return value === undefined || value === "" ? undefined : value;
}

/** Adds a value to the Set at `key`, creating the Set on first use. */
function push(bag, key, value) {
  if (value === undefined) return;
  let set = bag[key];
  if (!set) {
    set = new Set();
    bag[key] = set;
  }
  set.add(value);
}

/** Lexicographic minimum of a Set of strings. The default scalar reducer. */
function one(set) {
  if (!set || set.size === 0) return undefined;
  return [...set].sort()[0];
}

/** Sorted, de-duplicated array. The default array reducer. */
function many(set) {
  if (!set || set.size === 0) return [];
  return [...set].sort();
}

/** Largest finite number in a Set of numeric strings. */
function maxNumber(set) {
  if (!set || set.size === 0) return undefined;
  let best;
  for (const raw of set) {
    const n = Number(raw);
    if (!Number.isFinite(n)) continue;
    if (best === undefined || n > best) best = n;
  }
  return best;
}

/** Rounds to `places` decimals and drops a pointless trailing ".0". */
function round(value, places) {
  if (value === undefined) return undefined;
  const factor = 10 ** places;
  const rounded = Math.round(value * factor) / factor;
  return Object.is(rounded, -0) ? 0 : rounded;
}

/**
 * Parses a GeoSPARQL point. Note the order: WKT is `Point(longitude latitude)`,
 * which is the opposite of how everybody says it out loud.
 */
function parsePoint(wkt) {
  const match = /^Point\(\s*(-?[\d.eE+]+)\s+(-?[\d.eE+]+)\s*\)$/.exec(wkt ?? "");
  if (!match) return undefined;
  const lon = Number(match[1]);
  const lat = Number(match[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return undefined;
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return undefined;
  // Four decimals is about eleven meters, which is finer than the accuracy of
  // most of these statements and finer than any of these tools can use.
  return { lat: round(lat, 4), lon: round(lon, 4) };
}

/**
 * Regional indicator pair for an alpha-2 code. Derived, never fetched: the
 * flag emoji for "JP" is just the two letters shifted into the regional
 * indicator block, and rendering is the font's problem, not ours.
 */
function flagEmojiFor(iso2) {
  if (!/^[A-Z]{2}$/.test(iso2)) return undefined;
  return String.fromCodePoint(...[...iso2].map((letter) => 0x1f1e6 + letter.charCodeAt(0) - 65));
}

/** en.wikipedia article title from its sitelink URL. */
function wikipediaTitle(url) {
  if (!url) return undefined;
  const match = /^https:\/\/en\.wikipedia\.org\/wiki\/(.+)$/.exec(url);
  if (!match) return undefined;
  try {
    return decodeURIComponent(match[1]).replace(/_/g, " ");
  } catch {
    return match[1].replace(/_/g, " ");
  }
}

/**
 * Formats a UTC offset in hours as "UTC+05:30". Wikidata's P2907 is a plain
 * number, so 5.5 and -3 both arrive here.
 */
function formatUtcOffset(hours) {
  if (!Number.isFinite(hours) || Math.abs(hours) > 14) return undefined;
  const total = Math.round(hours * 60);
  const sign = total < 0 ? "-" : "+";
  const abs = Math.abs(total);
  const hh = String(Math.floor(abs / 60)).padStart(2, "0");
  const mm = String(abs % 60).padStart(2, "0");
  return `UTC${sign}${hh}:${mm}`;
}

/**
 * Normalizes a time zone item label to "UTC+HH:MM".
 *
 * Wikidata writes these with a real MINUS SIGN (U+2212) and uses PLUS MINUS
 * (U+00B1) for zero, so "UTC-04:00" typed on a keyboard never matches the
 * label as stored. Anything that is not an offset label (an IANA id, a name
 * like "Central European Time") returns undefined and is handled elsewhere.
 */
function normaliseUtcOffsetLabel(label) {
  const match = /^UTC\s*([+\-−±])\s*(\d{1,2}):(\d{2})$/.exec(label ?? "");
  if (!match) return undefined;
  const sign = match[1] === "-" || match[1] === "−" ? -1 : 1;
  const hours = Number(match[2]) + Number(match[3]) / 60;
  return formatUtcOffset(sign * hours);
}

/**
 * Standard time UTC offset of an IANA zone, derived with Intl.
 *
 * Wikidata records IANA identifiers for a lot of countries but records a
 * UTC offset for only some of them, so this fills the gap. Daylight saving
 * always moves a clock forward, so the standard offset is simply the smaller
 * of the January and July offsets, which makes this independent of when the
 * build runs. Two fixed instants are used so a rebuild cannot drift.
 */
const IANA_REFERENCE_INSTANTS = [Date.UTC(2025, 0, 15, 12), Date.UTC(2025, 6, 15, 12)];
const ianaOffsetCache = new Map();
function utcOffsetForIana(zone) {
  if (!zone) return undefined;
  if (ianaOffsetCache.has(zone)) return ianaOffsetCache.get(zone);
  let result;
  try {
    const offsets = IANA_REFERENCE_INSTANTS.map((instant) => {
      const parts = new Intl.DateTimeFormat("en-US", {
        timeZone: zone,
        timeZoneName: "longOffset",
      }).formatToParts(new Date(instant));
      const name = parts.find((part) => part.type === "timeZoneName")?.value ?? "";
      if (name === "GMT") return 0;
      const match = /^GMT([+-])(\d{1,2})(?::(\d{2}))?$/.exec(name);
      if (!match) return null;
      const sign = match[1] === "-" ? -1 : 1;
      return sign * (Number(match[2]) + Number(match[3] ?? 0) / 60);
    });
    const usable = offsets.filter((offset) => offset !== null);
    result = usable.length === 0 ? undefined : formatUtcOffset(Math.min(...usable));
  } catch {
    result = undefined;
  }
  ianaOffsetCache.set(zone, result);
  return result;
}

/** Sort key for a normalized offset. Lexicographic order puts "-" after "+". */
function offsetMinutes(offset) {
  const match = /^UTC([+-])(\d{2}):(\d{2})$/.exec(offset ?? "");
  if (!match) return 0;
  const sign = match[1] === "-" ? -1 : 1;
  return sign * (Number(match[2]) * 60 + Number(match[3]));
}

/**
 * Normalizes a P1406 script directionality label to a short code.
 *
 * The trap here is "vertical right-to-left". Wikidata gives every CJK script
 * two directionality values, horizontal left-to-right and vertical
 * right-to-left, because columns in vertical text run right to left. A naive
 * substring test on "right-to-left" therefore labels Japanese and Chinese as
 * RTL languages, which is nonsense in any horizontal UI. Vertical modes get
 * their own codes so they never collide with the bidirectional case.
 */
function normaliseDirection(label) {
  if (!label) return undefined;
  const text = label.toLowerCase().replace(/\s+/g, " ").replace(/-/g, " ");
  const vertical = text.includes("vertical") || text.includes("top to bottom");
  if (vertical) {
    if (text.includes("right to left")) return "vertical-rl";
    if (text.includes("left to right")) return "vertical-lr";
    return "vertical-rl";
  }
  if (text.includes("right to left")) return "rtl";
  if (text.includes("left to right")) return "ltr";
  if (text.includes("boustrophedon")) return "boustrophedon";
  return undefined;
}

/**
 * True when the label service gave up and returned the entity id. Those are
 * items with no English label, and an id is worse than nothing in a UI.
 */
function isPlaceholderLabel(label) {
  return label === undefined || /^Q\d+$/.test(label);
}

// ---------------------------------------------------------------------------
// Countries
// ---------------------------------------------------------------------------

/**
 * Every country query starts from the same subject set: anything carrying an
 * ISO 3166-1 alpha-2 code that has not been dissolved. P297 alone would also
 * match the Soviet Union, Yugoslavia, Czechoslovakia and East Germany, whose
 * codes collide with live ones (SU/RU is the ugly case), so the dissolution
 * filter is load bearing rather than tidy.
 */
const COUNTRY_SUBJECTS = `  ?c wdt:P297 ?iso2 .
  FILTER(!isBLANK(?c))
  FILTER NOT EXISTS { ?c wdt:P576 ?dissolvedAt }`;

/**
 * The label service, with the fallback chain that matters. Wikidata moved
 * language neutral labels to the `mul` pseudo-language, so items whose name is
 * the same everywhere (the euro, most ISO 15924 scripts, plenty of time zone
 * items) now have NO `en` label at all. Asking for "en" alone gets the entity
 * id back as the label, silently, for exactly the rows a lookup tool cares
 * about. "en,mul" prefers English and falls back to the neutral label.
 */
const LABEL_SERVICE = `  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,mul". }`;

async function buildCountries() {
  log("countries: querying Wikidata");
  const bag = new Map();

  const forQid = (row) => {
    const id = qidOf(v(row, "c"));
    const iso2 = v(row, "iso2");
    if (!id || !iso2) return null;
    let entry = bag.get(id);
    if (!entry) {
      entry = { qid: id, iso2 };
      bag.set(id, entry);
    }
    return entry;
  };

  const core = await sparql(
    `SELECT ?c ?cLabel ?iso2 ?iso3 ?isoNum ?article WHERE {
${COUNTRY_SUBJECTS}
  OPTIONAL { ?c wdt:P298 ?iso3 }
  OPTIONAL { ?c wdt:P299 ?isoNum }
  OPTIONAL { ?article schema:about ?c ; schema:isPartOf <https://en.wikipedia.org/> }
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c`,
    { ...queryOptions, label: "countries/core" },
  );
  for (const row of core) {
    const entry = forQid(row);
    if (!entry) continue;
    const label = v(row, "cLabel");
    push(entry, "name", isPlaceholderLabel(label) ? undefined : label);
    push(entry, "iso3", v(row, "iso3"));
    push(entry, "isoNumeric", v(row, "isoNum"));
    push(entry, "wikipedia", wikipediaTitle(v(row, "article")));
  }

  const names = await sparql(
    `SELECT ?c ?iso2 ?official ?demonym WHERE {
${COUNTRY_SUBJECTS}
  OPTIONAL { ?c wdt:P1448 ?official . FILTER(LANG(?official) = "en") }
  OPTIONAL { ?c wdt:P1549 ?demonym . FILTER(LANG(?demonym) = "en") }
}
ORDER BY ?iso2 ?c`,
    { ...queryOptions, label: "countries/names" },
  );
  for (const row of names) {
    const entry = forQid(row);
    if (!entry) continue;
    push(entry, "officialName", v(row, "official"));
    push(entry, "demonym", v(row, "demonym"));
  }

  const places = await sparql(
    `SELECT ?c ?iso2 ?capitalLabel ?continentLabel ?sideLabel WHERE {
${COUNTRY_SUBJECTS}
  OPTIONAL { ?c wdt:P36 ?capital }
  OPTIONAL { ?c wdt:P30 ?continent }
  OPTIONAL { ?c wdt:P1622 ?side }
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c`,
    { ...queryOptions, label: "countries/places" },
  );
  for (const row of places) {
    const entry = forQid(row);
    if (!entry) continue;
    for (const [field, variable] of [
      ["capital", "capitalLabel"],
      ["continent", "continentLabel"],
      ["drivingSide", "sideLabel"],
    ]) {
      const label = v(row, variable);
      push(entry, field, isPlaceholderLabel(label) ? undefined : label);
    }
  }

  const calling = await sparql(
    `SELECT ?c ?iso2 ?callingCode WHERE {
${COUNTRY_SUBJECTS}
  ?c wdt:P474 ?callingCode .
}
ORDER BY ?iso2 ?c ?callingCode`,
    { ...queryOptions, label: "countries/calling-codes" },
  );
  for (const row of calling) {
    const entry = forQid(row);
    if (entry) push(entry, "callingCodes", v(row, "callingCode"));
  }

  const currencies = await sparql(
    `SELECT ?c ?iso2 ?currency ?currencyLabel ?currencyCode WHERE {
${COUNTRY_SUBJECTS}
  ?c wdt:P38 ?currency .
  OPTIONAL { ?currency wdt:P498 ?currencyCode }
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c ?currency`,
    { ...queryOptions, label: "countries/currencies" },
  );
  for (const row of currencies) {
    const entry = forQid(row);
    if (!entry) continue;
    const label = v(row, "currencyLabel");
    const code = v(row, "currencyCode");
    // Encoded as "CODE\tName" so the pair survives the Set and stays sortable
    // by code, then split apart in the reduce below.
    push(entry, "currencies", `${code ?? ""}\t${isPlaceholderLabel(label) ? "" : label}`);
  }

  const tlds = await sparql(
    `SELECT ?c ?iso2 ?tld ?tldLabel WHERE {
${COUNTRY_SUBJECTS}
  ?c wdt:P78 ?tld .
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c ?tld`,
    { ...queryOptions, label: "countries/tlds" },
  );
  for (const row of tlds) {
    const entry = forQid(row);
    if (!entry) continue;
    const label = v(row, "tldLabel");
    if (!isPlaceholderLabel(label))
      push(entry, "tlds", label.startsWith(".") ? label : `.${label}`);
  }

  const zones = await sparql(
    `SELECT ?c ?iso2 ?tz ?tzLabel ?tzIana ?tzOffset WHERE {
${COUNTRY_SUBJECTS}
  ?c wdt:P421 ?tz .
  OPTIONAL { ?tz wdt:P6687 ?tzIana }
  OPTIONAL { ?tz wdt:P2907 ?tzOffset }
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c ?tz`,
    { ...queryOptions, label: "countries/time-zones" },
  );
  // P421 points at three different kinds of item: a UTC offset ("UTC+01:00"),
  // an IANA zone ("Europe/Andorra") and a named zone ("Central European
  // Time"). Offsets are recovered from the label, then P2907, then Intl on the
  // IANA id, so a country ends up with both views however Wikidata modeled it.
  for (const row of zones) {
    const entry = forQid(row);
    if (!entry) continue;
    const iana = v(row, "tzIana");
    push(entry, "ianaTimeZones", iana);
    const label = v(row, "tzLabel");
    const offset =
      normaliseUtcOffsetLabel(isPlaceholderLabel(label) ? undefined : label) ??
      formatUtcOffset(Number(v(row, "tzOffset"))) ??
      utcOffsetForIana(iana);
    push(entry, "timeZones", offset);
  }

  const plugs = await sparql(
    `SELECT ?c ?iso2 ?plug ?plugLabel ?plugAlt WHERE {
${COUNTRY_SUBJECTS}
  ?c wdt:P2853 ?plug .
  OPTIONAL { ?plug skos:altLabel ?plugAlt . FILTER(LANG(?plugAlt) = "en") }
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c ?plug`,
    { ...queryOptions, label: "countries/plug-types" },
  );
  // Wikidata labels plug items by their standard ("NEMA 1-15"), while the
  // familiar names ("Type A") live in the aliases. Resolve every plug item
  // once, preferring a "Type X" alias, then apply that name per country.
  const plugName = new Map();
  for (const row of plugs) {
    const id = qidOf(v(row, "plug"));
    if (!id) continue;
    if (!plugName.has(id)) plugName.set(id, { label: undefined, types: new Set() });
    const record = plugName.get(id);
    const label = v(row, "plugLabel");
    if (!isPlaceholderLabel(label)) record.label = label;
    const alt = v(row, "plugAlt");
    if (alt && /^type\s+[a-z]$/i.test(alt.trim())) {
      const letter = alt.trim().slice(-1).toUpperCase();
      record.types.add(`Type ${letter}`);
    }
  }
  for (const row of plugs) {
    const entry = forQid(row);
    const id = qidOf(v(row, "plug"));
    if (!entry || !id) continue;
    const record = plugName.get(id);
    const name = [...record.types].sort()[0] ?? record.label;
    push(entry, "plugTypes", name);
  }

  const population = await sparql(
    `SELECT ?c ?iso2 ?pop ?time ?rank WHERE {
${COUNTRY_SUBJECTS}
  ?c p:P1082 ?statement .
  ?statement ps:P1082 ?pop .
  ?statement wikibase:rank ?rank .
  OPTIONAL { ?statement pq:P585 ?time }
}
ORDER BY ?iso2 ?c ?time ?pop`,
    { ...queryOptions, label: "countries/population" },
  );
  // Population is picked by (rank, point in time, value) so the answer is the
  // most recent authoritative figure rather than whichever row arrived last.
  const popBest = new Map();
  for (const row of population) {
    const id = qidOf(v(row, "c"));
    const rank = v(row, "rank") ?? "";
    if (!id || rank.endsWith("DeprecatedRank")) continue;
    const value = Number(v(row, "pop"));
    if (!Number.isFinite(value) || value <= 0) continue;
    const candidate = {
      preferred: rank.endsWith("PreferredRank") ? 1 : 0,
      time: v(row, "time") ?? "",
      value,
    };
    const current = popBest.get(id);
    if (
      !current ||
      candidate.preferred > current.preferred ||
      (candidate.preferred === current.preferred && candidate.time > current.time) ||
      (candidate.preferred === current.preferred &&
        candidate.time === current.time &&
        candidate.value > current.value)
    ) {
      popBest.set(id, candidate);
    }
    forQid(row);
  }

  const areas = await sparql(
    `SELECT ?c ?iso2 ?areaSqM ?rank WHERE {
${COUNTRY_SUBJECTS}
  ?c p:P2046 ?statement .
  ?statement wikibase:rank ?rank .
  ?statement psn:P2046 ?node .
  ?node wikibase:quantityAmount ?areaSqM .
}
ORDER BY ?iso2 ?c ?areaSqM`,
    { ...queryOptions, label: "countries/area" },
  );
  // psn: is the normalized value, always in square meters whatever unit the
  // statement was written in. wdt:P2046 is the raw number and mixes km2 with
  // square miles, so it is not usable without reading the unit.
  const areaBest = new Map();
  for (const row of areas) {
    const id = qidOf(v(row, "c"));
    const rank = v(row, "rank") ?? "";
    if (!id || rank.endsWith("DeprecatedRank")) continue;
    const sqm = Number(v(row, "areaSqM"));
    if (!Number.isFinite(sqm) || sqm <= 0) continue;
    const candidate = { preferred: rank.endsWith("PreferredRank") ? 1 : 0, sqm };
    const current = areaBest.get(id);
    if (
      !current ||
      candidate.preferred > current.preferred ||
      (candidate.preferred === current.preferred && candidate.sqm > current.sqm)
    ) {
      areaBest.set(id, candidate);
    }
    forQid(row);
  }

  const dissolved = await sparql(
    `SELECT ?c ?cLabel ?iso2 WHERE {
  ?c wdt:P297 ?iso2 .
  ?c wdt:P576 ?dissolvedAt .
  FILTER(!isBLANK(?c))
${LABEL_SERVICE}
}
ORDER BY ?iso2 ?c`,
    { ...queryOptions, label: "countries/dissolved" },
  );

  // Reduce every bag to one row, then dedupe by alpha-2. The tie break prefers
  // the entity with the most filled fields, which is always the live country
  // rather than a same-code redirect or a disputed duplicate.
  const byIso2 = new Map();
  for (const entry of bag.values()) {
    const currencyPairs = many(entry.currencies)
      .map((packed) => {
        const [code, name] = packed.split("\t");
        return { code: code || undefined, name: name || undefined };
      })
      .filter((item) => item.code || item.name);

    const row = {
      qid: entry.qid,
      name: one(entry.name) ?? entry.iso2,
      officialName: one(entry.officialName),
      iso2: entry.iso2,
      iso3: one(entry.iso3),
      isoNumeric: one(entry.isoNumeric),
      callingCodes: many(entry.callingCodes),
      currencies: currencyPairs,
      tlds: many(entry.tlds),
      timeZones: many(entry.timeZones).sort((a, b) => offsetMinutes(a) - offsetMinutes(b)),
      ianaTimeZones: many(entry.ianaTimeZones),
      drivingSide: one(entry.drivingSide),
      plugTypes: many(entry.plugTypes),
      capital: one(entry.capital),
      continent: one(entry.continent),
      population: popBest.get(entry.qid)?.value,
      areaKm2: areaBest.has(entry.qid) ? round(areaBest.get(entry.qid).sqm / 1e6, 2) : undefined,
      flagEmoji: flagEmojiFor(entry.iso2),
      wikipedia: one(entry.wikipedia),
      demonym: one(entry.demonym),
    };
    const filled = Object.values(row).filter(
      (value) => value !== undefined && !(Array.isArray(value) && value.length === 0),
    ).length;

    const existing = byIso2.get(entry.iso2);
    if (
      !existing ||
      filled > existing.filled ||
      (filled === existing.filled && row.qid < existing.row.qid)
    ) {
      byIso2.set(entry.iso2, { row, filled });
    }
  }

  const countries = [...byIso2.values()]
    .map((item) => item.row)
    .sort((a, b) => a.name.localeCompare(b.name, "en") || a.iso2.localeCompare(b.iso2));

  const liveCodes = new Set(countries.map((country) => country.iso2));
  const ghosts = [];
  for (const row of dissolved) {
    const iso2 = v(row, "iso2");
    if (!iso2 || liveCodes.has(iso2)) continue;
    const label = v(row, "cLabel");
    ghosts.push(`${iso2} (${isPlaceholderLabel(label) ? qidOf(v(row, "c")) : label})`);
  }
  if (ghosts.length) {
    log(
      `countries: skipped ${ghosts.length} codes held only by dissolved states: ${[...new Set(ghosts)].sort().join(", ")}`,
    );
  }

  const header = `/**
 * ISO 3166-1 countries and territories, generated from Wikidata.
 *
 * DO NOT EDIT. Written by scripts/prepare-wikidata.mjs; gitignored.
 *
 * One row per alpha-2 code. Entities with a dissolution date (P576) are
 * excluded, so SU, YU, CS and friends are absent and DE is Germany rather
 * than East Germany. Where two live entities share a code, the row with more
 * filled fields wins.
 *
 * Field notes a tool author needs:
 *  - \`iso2\` here is ISO 3166-1 alpha-2. In wikidata-languages.ts the field
 *    called \`iso2\` is ISO 639-2, which is a completely different register.
 *  - \`areaKm2\` is square kilometers, normalized from Wikidata's mixed units.
 *  - \`timeZones\` are standard time UTC offsets, normalized to "UTC+01:00" /
 *    "UTC-05:00" with an ASCII sign. Wikidata stores them with a real minus
 *    sign (U+2212), so never compare against a raw label. \`ianaTimeZones\`
 *    are IANA identifiers ("Europe/Paris"); the two arrays are not parallel
 *    and either can be empty on its own.
 *  - \`flagEmoji\` is derived from the alpha-2 code, not fetched, so it exists
 *    for every row and renders only as well as the reader's font allows.
 *  - \`population\` is the most recent statement by rank then point in time.
 *
 * Source: Wikidata, CC0 1.0.
 */`;

  const body = `/** One currency in circulation, with its ISO 4217 code where Wikidata has one. */
export interface CountryCurrency {
  /** ISO 4217 alphabetic code, for example "EUR". Absent for a few local currencies. */
  code?: string;
  /** English name of the currency. */
  name?: string;
}

/** A country or territory holding an ISO 3166-1 alpha-2 code. */
export interface Country {
  /** Wikidata entity id, for example "Q142". */
  qid: string;
  /** English label, for example "France". */
  name: string;
  /** Official long form (P1448), for example "French Republic". */
  officialName?: string;
  /** ISO 3166-1 alpha-2 code, for example "FR". Unique across this array. */
  iso2: string;
  /** ISO 3166-1 alpha-3 code, for example "FRA". */
  iso3?: string;
  /** ISO 3166-1 numeric code as a zero padded string, for example "250". */
  isoNumeric?: string;
  /** International calling codes, for example ["+33"]. Sorted. */
  callingCodes: string[];
  /** Currencies in circulation. Sorted by ISO 4217 code. */
  currencies: CountryCurrency[];
  /** Country code top level domains, for example [".fr"]. Sorted. */
  tlds: string[];
  /** Standard time UTC offsets, for example ["UTC+01:00"]. Sorted west to east. */
  timeZones: string[];
  /** IANA zone identifiers where Wikidata records them. Not parallel to timeZones. */
  ianaTimeZones: string[];
  /** Side of the road traffic drives on, "right" or "left". */
  drivingSide?: string;
  /** Domestic mains plug types, for example ["Type C", "Type E"]. Sorted. */
  plugTypes: string[];
  /** English label of the capital city. */
  capital?: string;
  /** English label of the continent. One value even when Wikidata lists two. */
  continent?: string;
  /** Most recent recorded population. */
  population?: number;
  /** Total area in square kilometers. */
  areaKm2?: number;
  /** Regional indicator flag emoji derived from the alpha-2 code. */
  flagEmoji?: string;
  /** English Wikipedia article title. */
  wikipedia?: string;
  /** Demonym in English, for example "French". */
  demonym?: string;
}

/** Every ISO 3166-1 alpha-2 holder that still exists, sorted by English name. */
export const COUNTRIES: Country[] = ${rowsLiteral(countries)};`;

  const result = writeGeneratedModule({
    path: join(generatedDir, "wikidata-countries.ts"),
    header,
    body,
    counts: { countries: countries.length },
  });
  log(
    `countries: ${countries.length} rows, ${result.bytes} bytes` +
      (result.changed ? "" : " (unchanged)"),
  );
  return { countries, result };
}

// ---------------------------------------------------------------------------
// Airports
// ---------------------------------------------------------------------------

const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

function airportQuery(prefix) {
  return `SELECT ?a ?aLabel ?iata ?icao ?coord ?elevM ?ciso2 ?servedLabel ?admin1Label ?tzLabel ?tzIana ?article WHERE {
  ?a wdt:P238 ?iata .
  FILTER(STRSTARTS(?iata, "${prefix}"))
  FILTER(!isBLANK(?a))
  OPTIONAL { ?a wdt:P239 ?icao }
  OPTIONAL { ?a wdt:P625 ?coord }
  OPTIONAL { ?a p:P2044/psn:P2044/wikibase:quantityAmount ?elevM }
  OPTIONAL { ?a wdt:P17 ?country . OPTIONAL { ?country wdt:P297 ?ciso2 } }
  OPTIONAL { ?a wdt:P931 ?served }
  OPTIONAL { ?a wdt:P131 ?admin1 }
  OPTIONAL { ?a wdt:P421 ?tz . OPTIONAL { ?tz wdt:P6687 ?tzIana } }
  OPTIONAL { ?article schema:about ?a ; schema:isPartOf <https://en.wikipedia.org/> }
${LABEL_SERVICE}
}
ORDER BY ?iata ?a`;
}

async function buildAirports() {
  log("airports: querying Wikidata by IATA prefix");
  // The subject set is every non-blank entity with an IATA airport code
  // (P238), not just instances of Q1248784. "Airport" does not subsume
  // aerodrome, airbase or heliport in Wikidata's class tree, and those hold
  // roughly 1,300 perfectly real IATA codes (AAL Aalborg, ACH Altenrhein,
  // ADW Andrews). Blank nodes have to be filtered: an unknown-value P238
  // subject arrives as a .well-known/genid URI.
  const rows = await sparqlSharded(
    LETTERS,
    airportQuery,
    (prefix) => (prefix.length >= 3 ? null : LETTERS.map((letter) => prefix + letter)),
    (prefix) => `airports/${prefix}`,
    queryOptions,
  );

  const bag = new Map();
  for (const row of rows) {
    const qid = qidOf(v(row, "a"));
    const iata = v(row, "iata");
    if (!qid || !iata || !/^[A-Z]{3}$/.test(iata)) continue;
    const key = `${iata}\t${qid}`;
    let entry = bag.get(key);
    if (!entry) {
      entry = { qid, iata };
      bag.set(key, entry);
    }
    const label = v(row, "aLabel");
    push(entry, "name", isPlaceholderLabel(label) ? undefined : label);
    push(entry, "icao", v(row, "icao"));
    push(entry, "coord", v(row, "coord"));
    push(entry, "elevM", v(row, "elevM"));
    push(entry, "country", v(row, "ciso2"));
    const served = v(row, "servedLabel");
    if (!isPlaceholderLabel(served)) push(entry, "served", served);
    const admin1 = v(row, "admin1Label");
    if (!isPlaceholderLabel(admin1)) push(entry, "admin1", admin1);
    const tz = v(row, "tzLabel");
    if (!isPlaceholderLabel(tz)) push(entry, "tzLabel", tz);
    push(entry, "tzIana", v(row, "tzIana"));
    push(entry, "wikipedia", wikipediaTitle(v(row, "article")));
  }

  const candidates = [];
  for (const entry of bag.values()) {
    const point = parsePoint(one(entry.coord));
    // P931 (place served) is the airport's city; P131 (located in) is the
    // administrative parent and is the fallback, which for a rural field is
    // often a district rather than a town.
    const city = one(entry.served) ?? one(entry.admin1);
    candidates.push({
      qid: entry.qid,
      name: one(entry.name) ?? entry.iata,
      iata: entry.iata,
      icao: one(entry.icao),
      city,
      country: one(entry.country),
      lat: point?.lat,
      lon: point?.lon,
      elevationM: round(maxNumber(entry.elevM), 0),
      timeZone: one(entry.tzIana) ?? one(entry.tzLabel),
      wikipedia: one(entry.wikipedia),
    });
  }

  // Dedupe by IATA. An ICAO code is the strongest signal that a row is the
  // real airport rather than a stub, then coordinates, then field count.
  const score = (row) =>
    (row.icao ? 8 : 0) +
    (row.lat !== undefined ? 4 : 0) +
    (row.country ? 2 : 0) +
    (row.wikipedia ? 1 : 0);
  const byIata = new Map();
  let collisions = 0;
  for (const row of candidates) {
    const existing = byIata.get(row.iata);
    if (!existing) {
      byIata.set(row.iata, row);
      continue;
    }
    collisions += 1;
    const better =
      score(row) > score(existing) ||
      (score(row) === score(existing) && row.qid.localeCompare(existing.qid) < 0);
    if (better) byIata.set(row.iata, row);
  }

  const airports = [...byIata.values()].sort((a, b) => a.iata.localeCompare(b.iata));
  const withIcao = airports.filter((a) => a.icao).length;
  const withCoords = airports.filter((a) => a.lat !== undefined).length;

  const header = `/**
 * Airports and other IATA code holders, generated from Wikidata.
 *
 * DO NOT EDIT. Written by scripts/prepare-wikidata.mjs; gitignored.
 *
 * The subject set is every entity with an IATA airport code (P238), which is
 * deliberately wider than "instance of airport". Wikidata's class tree does
 * not put aerodromes, airbases and heliports under airport, and those hold
 * around 1,100 real codes: AAL, ACH and ADW are all missing from the narrow
 * set.
 *
 * Consequences a tool author has to design for:
 *  - A few rows are cities, not airports. LON and PAR are the Wikidata items
 *    for London and Paris, so their name, coordinates and Wikipedia title
 *    describe the city and they have no ICAO code. NYC is simply absent,
 *    because New York City's item carries no P238. Metro codes are not
 *    modeled consistently, so do not build a feature on them.
 *  - Where a civil airport and a military field share a code, the dedup keeps
 *    whichever entity has more filled fields. AAL resolves to "Aalborg Air
 *    Base" rather than Aalborg Airport for that reason.
 *  - \`icao\`, \`city\`, \`lat\`, \`lon\`, \`elevationM\` and \`timeZone\` are all
 *    optional and really are missing on some rows. Guard on them.
 *
 * One row per IATA code. Where several entities claim the same code the row
 * with an ICAO code and coordinates wins.
 *
 * Source: Wikidata, CC0 1.0.
 */`;

  const body = `/** An entity holding an IATA airport code. */
export interface Airport {
  /** Wikidata entity id, for example "Q8686". */
  qid: string;
  /** English label, for example "Chicago O'Hare International Airport". */
  name: string;
  /** IATA airport code, for example "ORD". Unique across this array. */
  iata: string;
  /** ICAO airport code, for example "KORD". Absent for heliports and metro codes. */
  icao?: string;
  /** City served (P931), falling back to the administrative parent (P131). */
  city?: string;
  /** ISO 3166-1 alpha-2 code of the country, for joining to COUNTRIES. */
  country?: string;
  /** Latitude in decimal degrees, five decimal places. */
  lat?: number;
  /** Longitude in decimal degrees, five decimal places. */
  lon?: number;
  /** Elevation above sea level in meters, normalized from Wikidata's units. */
  elevationM?: number;
  /** IANA zone id ("America/Chicago") when known, else a UTC offset label. */
  timeZone?: string;
  /** English Wikipedia article title. */
  wikipedia?: string;
}

/** Every IATA code holder in Wikidata, sorted by IATA code. */
export const AIRPORTS: Airport[] = ${rowsLiteral(airports)};`;

  const result = writeGeneratedModule({
    path: join(generatedDir, "wikidata-airports.ts"),
    header,
    body,
    counts: { airports: airports.length, withIcao, withCoordinates: withCoords },
  });
  log(
    `airports: ${airports.length} rows (${withIcao} with ICAO, ${withCoords} with coordinates, ` +
      `${collisions} code collisions resolved), ${result.bytes} bytes` +
      (result.changed ? "" : " (unchanged)"),
  );
  return { airports, result };
}

// ---------------------------------------------------------------------------
// Languages and scripts
// ---------------------------------------------------------------------------

const LOWER = "abcdefghijklmnopqrstuvwxyz".split("");

function languageQuery(shard) {
  const constraint =
    shard === "iso1"
      ? `  ?l wdt:P218 ?anyIso1 .`
      : `  ?l wdt:P220 ?anyIso3 .\n  FILTER(STRSTARTS(?anyIso3, "${shard}"))`;
  return `SELECT ?l ?lLabel ?iso1 ?iso2b ?iso3 ?native ?speakers ?famLabel ?article ?script ?scriptCode ?scriptLabel ?dirLabel WHERE {
${constraint}
  FILTER(!isBLANK(?l))
  OPTIONAL { ?l wdt:P218 ?iso1 }
  OPTIONAL { ?l wdt:P219 ?iso2b }
  OPTIONAL { ?l wdt:P220 ?iso3 }
  OPTIONAL { ?l wdt:P1705 ?native }
  OPTIONAL { ?l wdt:P1098 ?speakers }
  OPTIONAL { ?l wdt:P279 ?fam }
  OPTIONAL {
    ?l wdt:P282+ ?script .
    ?script wdt:P506 ?scriptCode .
    OPTIONAL { ?script wdt:P1406 ?dir }
  }
  OPTIONAL { ?article schema:about ?l ; schema:isPartOf <https://en.wikipedia.org/> }
${LABEL_SERVICE}
}
ORDER BY ?l`;
}

async function buildLanguages() {
  log("languages: querying Wikidata by ISO 639-3 prefix");
  const shards = [...LOWER, "iso1"];
  const rows = await sparqlSharded(
    shards,
    languageQuery,
    (shard) =>
      shard === "iso1" || shard.length >= 3 ? null : LOWER.map((letter) => shard + letter),
    (shard) => `languages/${shard}`,
    queryOptions,
  );

  const bag = new Map();
  for (const row of rows) {
    const qid = qidOf(v(row, "l"));
    if (!qid) continue;
    let entry = bag.get(qid);
    if (!entry) {
      entry = { qid };
      bag.set(qid, entry);
    }
    const label = v(row, "lLabel");
    push(entry, "name", isPlaceholderLabel(label) ? undefined : label);
    push(entry, "iso1", v(row, "iso1"));
    push(entry, "iso2b", v(row, "iso2b"));
    push(entry, "iso3", v(row, "iso3"));
    push(entry, "native", v(row, "native"));
    push(entry, "speakers", v(row, "speakers"));
    const family = v(row, "famLabel");
    if (!isPlaceholderLabel(family)) push(entry, "family", family);
    push(entry, "wikipedia", wikipediaTitle(v(row, "article")));
    const code = v(row, "scriptCode");
    const scriptLabel = v(row, "scriptLabel");
    if (code) {
      push(entry, "scripts", `${code}\t${isPlaceholderLabel(scriptLabel) ? "" : scriptLabel}`);
      const direction = normaliseDirection(v(row, "dirLabel"));
      push(entry, "directions", direction);
    }
  }

  const scriptRows = await sparql(
    `SELECT ?s ?sLabel ?code ?dirLabel WHERE {
  ?s wdt:P506 ?code .
  FILTER(!isBLANK(?s))
  OPTIONAL { ?s wdt:P1406 ?dir }
${LABEL_SERVICE}
}
ORDER BY ?code ?s`,
    { ...queryOptions, label: "languages/scripts" },
  );
  const scriptBag = new Map();
  for (const row of scriptRows) {
    const code = v(row, "code");
    if (!code || !/^[A-Z][a-z]{3}$/.test(code)) continue;
    let entry = scriptBag.get(code);
    if (!entry) {
      entry = { code };
      scriptBag.set(code, entry);
    }
    const label = v(row, "sLabel");
    if (!isPlaceholderLabel(label)) push(entry, "name", label);
    push(entry, "direction", normaliseDirection(v(row, "dirLabel")));
  }
  const scripts = [...scriptBag.values()]
    .map((entry) => ({
      code: entry.code,
      name: one(entry.name) ?? entry.code,
      direction: pickDirection(entry.direction),
    }))
    .sort((a, b) => a.code.localeCompare(b.code));
  const scriptDirection = new Map(scripts.map((script) => [script.code, script.direction]));
  const scriptName = new Map(scripts.map((script) => [script.code, script.name]));

  const languages = [];
  for (const entry of bag.values()) {
    const iso1 = one(entry.iso1);
    const iso2b = one(entry.iso2b);
    const iso3 = one(entry.iso3);
    if (!iso1 && !iso2b && !iso3) continue;
    const scriptList = many(entry.scripts)
      .map((packed) => {
        const [code, name] = packed.split("\t");
        return { code, name: name || scriptName.get(code) || undefined };
      })
      .filter((script) => /^[A-Z][a-z]{3}$/.test(script.code));
    // Direction comes from the language's own scripts, taking the script
    // registry's answer when this language did not carry one.
    const directions = new Set([
      ...many(entry.directions),
      ...scriptList.map((script) => scriptDirection.get(script.code)).filter(Boolean),
    ]);
    const nativeName = one(entry.native);
    languages.push({
      qid: entry.qid,
      name: one(entry.name) ?? iso3 ?? iso1 ?? iso2b,
      nativeName,
      iso1,
      iso2: iso2b,
      iso3,
      scripts: scriptList,
      direction: directionFromNativeName(nativeName) ?? pickDirection(directions),
      speakers: maxNumber(entry.speakers),
      family: one(entry.family),
      wikipedia: one(entry.wikipedia),
    });
  }

  languages.sort(
    (a, b) =>
      a.name.localeCompare(b.name, "en") ||
      (a.iso3 ?? "").localeCompare(b.iso3 ?? "") ||
      a.qid.localeCompare(b.qid),
  );

  const withIso1 = languages.filter((l) => l.iso1).length;
  const rtl = languages.filter((l) => l.direction === "rtl").length;

  const header = `/**
 * ISO 639 languages and ISO 15924 scripts, generated from Wikidata.
 *
 * DO NOT EDIT. Written by scripts/prepare-wikidata.mjs; gitignored.
 *
 * Read the field names carefully. On a Language, \`iso2\` is the ISO 639-2
 * bibliographic code (three letters, "fre"), NOT a country alpha-2 code. The
 * Country type in wikidata-countries.ts uses the same field name for ISO
 * 3166-1 alpha-2, so a file importing both should alias one of them.
 *
 * Other things worth knowing:
 *  - \`family\` is the direct "subclass of" (P279) parent, which Wikidata uses
 *    for language family membership. It is often a subfamily ("Semitic")
 *    rather than the top level family ("Afro-Asiatic"). There is no dedicated
 *    language family property to use instead.
 *  - \`scripts\` follows P282 transitively, because Wikidata usually attaches a
 *    language to its own alphabet ("English alphabet") rather than to the ISO
 *    15924 script, and only the latter carries a code. Following one hop is
 *    what turns English from "no scripts" into "Latn".
 *    \`scripts\` is still incomplete for plenty of languages, French among
 *    them, because Wikidata never connects "French alphabet" to "Latin
 *    script". Treat an empty array as "not recorded", never as "no script".
 *  - \`direction\` is read off the native label rather than off \`scripts\`,
 *    which is why it is right where the script list is not. Persian lists
 *    Arabic, Cyrillic and Latin scripts and Japanese lists a vertical
 *    right-to-left mode, so no rule over that list gets both languages right.
 *    A language's own name is written in its own script, so it answers
 *    directly. Languages with no native label fall back to the script set.
 *  - \`speakers\` is the largest figure Wikidata records, which for widely
 *    spoken languages varies by source and by whether L2 speakers count.
 *  - Most ISO 639-3 entries are small languages with no script, no speaker
 *    count and no English Wikipedia article. Only the fields that exist are
 *    emitted.
 *
 * Source: Wikidata, CC0 1.0.
 */`;

  const body = `/**
 * Text direction, normalized from Wikidata's script directionality labels.
 * "vertical-rl" is the CJK vertical mode, where columns run right to left; it
 * is not the same thing as "rtl" and must not be treated as one.
 */
export type TextDirection = "ltr" | "rtl" | "vertical-rl" | "vertical-lr" | "boustrophedon";

/** A writing system attached to a language. */
export interface LanguageScript {
  /** ISO 15924 alpha-4 code, for example "Latn". */
  code: string;
  /** English name of the script, for example "Latin script". */
  name?: string;
}

/** A language carrying at least one ISO 639 code. */
export interface Language {
  /** Wikidata entity id, for example "Q1860". */
  qid: string;
  /** English label, for example "English". */
  name: string;
  /** Native label (P1705), for example "Nihongo" written in Japanese. */
  nativeName?: string;
  /** ISO 639-1 two letter code, for example "en". Only 180 or so languages have one. */
  iso1?: string;
  /** ISO 639-2 bibliographic three letter code. NOT a country code. */
  iso2?: string;
  /** ISO 639-3 three letter code, for example "eng". Present for almost every row. */
  iso3?: string;
  /** Writing systems with an ISO 15924 code. Sorted by code, often empty. */
  scripts: LanguageScript[];
  /** Dominant text direction derived from those scripts. */
  direction?: TextDirection;
  /** Largest speaker count Wikidata records. */
  speakers?: number;
  /** Direct P279 parent, usually a language family or subfamily. */
  family?: string;
  /** English Wikipedia article title. */
  wikipedia?: string;
}

/** An ISO 15924 script. */
export interface Script {
  /** ISO 15924 alpha-4 code, for example "Arab". */
  code: string;
  /** English name of the script. */
  name: string;
  /** Text direction where Wikidata records one. */
  direction?: TextDirection;
}

/** Every language with an ISO 639-1, 639-2 or 639-3 code, sorted by English name. */
export const LANGUAGES: Language[] = ${rowsLiteral(languages)};

/** Every ISO 15924 script, sorted by code. */
export const SCRIPTS: Script[] = ${rowsLiteral(scripts)};`;

  const result = writeGeneratedModule({
    path: join(generatedDir, "wikidata-languages.ts"),
    header,
    body,
    counts: { languages: languages.length, scripts: scripts.length, withIso639_1: withIso1 },
  });
  log(
    `languages: ${languages.length} rows (${withIso1} with ISO 639-1, ${rtl} right to left), ` +
      `${scripts.length} scripts, ${result.bytes} bytes` +
      (result.changed ? "" : " (unchanged)"),
  );
  return { languages, scripts, result };
}

/**
 * The Unicode scripts that are written right to left. This is the standard's
 * own set, not a judgment call, and it is stable: scripts do not change
 * direction. Wikidata cannot supply it, because P1406 describes a script in
 * isolation and every CJK script carries a vertical right-to-left value.
 */
const RTL_SCRIPT_TEST = new RegExp(
  "[" +
    "\\p{Script=Arabic}\\p{Script=Hebrew}\\p{Script=Syriac}\\p{Script=Thaana}" +
    "\\p{Script=Nko}\\p{Script=Samaritan}\\p{Script=Mandaic}\\p{Script=Adlam}" +
    "\\p{Script=Hanifi_Rohingya}\\p{Script=Mende_Kikakui}\\p{Script=Cypriot}" +
    "\\p{Script=Imperial_Aramaic}\\p{Script=Phoenician}\\p{Script=Old_South_Arabian}" +
    "\\p{Script=Avestan}\\p{Script=Old_Turkic}\\p{Script=Old_Hungarian}" +
    "\\p{Script=Kharoshthi}\\p{Script=Nabataean}\\p{Script=Palmyrene}" +
    "\\p{Script=Inscriptional_Pahlavi}\\p{Script=Inscriptional_Parthian}" +
    "\\p{Script=Manichaean}\\p{Script=Psalter_Pahlavi}\\p{Script=Hatran}" +
    "\\p{Script=Old_North_Arabian}\\p{Script=Elymaic}\\p{Script=Yezidi}" +
    "\\p{Script=Old_Sogdian}\\p{Script=Sogdian}\\p{Script=Chorasmian}" +
    "\\p{Script=Garay}" +
    "]",
  "u",
);
const HAS_LETTER = /\p{L}/u;

/**
 * Text direction of a language, read off its own native name.
 *
 * This is the one signal that actually works. Deriving direction from the
 * scripts Wikidata attaches to a language fails in both directions: Persian
 * lists Arabic, Cyrillic and Latin, so "any LTR means LTR" calls Persian an
 * LTR language, while Japanese lists a vertical right-to-left mode, so "any
 * RTL means RTL" calls Japanese an RTL language. The native label (P1705) is
 * by definition written in the language's own script, so its characters
 * answer the question directly. Returns undefined when there is no native
 * label to read, and the caller falls back to the script set.
 */
function directionFromNativeName(nativeName) {
  if (!nativeName) return undefined;
  if (RTL_SCRIPT_TEST.test(nativeName)) return "rtl";
  if (HAS_LETTER.test(nativeName)) return "ltr";
  return undefined;
}

/**
 * Reduces a set of directionality values to the one a caller should lay text
 * out with.
 *
 * Horizontal left to right wins outright: a script that supports both a
 * horizontal LTR mode and a vertical mode (every CJK script) is LTR in any
 * ordinary web layout. RTL is only reported for scripts that have no
 * horizontal LTR mode at all, which is exactly Arabic, Hebrew, Thaana, Syriac
 * and their relatives.
 */
function pickDirection(set) {
  const values = set instanceof Set ? set : new Set(set ?? []);
  for (const candidate of ["ltr", "rtl", "vertical-rl", "vertical-lr", "boustrophedon"]) {
    if (values.has(candidate)) return candidate;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Cities (SQLite)
// ---------------------------------------------------------------------------

/**
 * Population bands. Two class roots are queried: Q515 (city) as one cheap
 * sweep, and Q486972 (human settlement) band by band. The settlement subclass
 * tree is enormous, so an unbanded settlement query is a guaranteed timeout;
 * a band is not, and any band WDQS still refuses is halved automatically.
 */
const CITY_SHARDS = [
  { cls: "Q515", lo: 100_000, hi: null },
  { cls: "Q486972", lo: 100_000, hi: 125_000 },
  { cls: "Q486972", lo: 125_000, hi: 150_000 },
  { cls: "Q486972", lo: 150_000, hi: 200_000 },
  { cls: "Q486972", lo: 200_000, hi: 300_000 },
  { cls: "Q486972", lo: 300_000, hi: 500_000 },
  { cls: "Q486972", lo: 500_000, hi: 1_000_000 },
  { cls: "Q486972", lo: 1_000_000, hi: 2_000_000 },
  { cls: "Q486972", lo: 2_000_000, hi: null },
];

function cityQuery(shard) {
  const bound = shard.hi === null ? "" : ` && ?pop <= ${shard.hi}`;
  return `SELECT ?c ?cLabel ?pop ?coord ?ciso2 ?countryLabel ?admin1Label ?elevM ?tzLabel ?tzIana ?article WHERE {
  {
    SELECT ?c ?pop WHERE {
      ?c wdt:P1082 ?pop .
      FILTER(?pop > ${shard.lo}${bound})
      ?c wdt:P31 ?type .
      ?type wdt:P279* wd:${shard.cls} .
      FILTER(!isBLANK(?c))
    }
  }
  OPTIONAL { ?c wdt:P625 ?coord }
  OPTIONAL { ?c wdt:P17 ?country . OPTIONAL { ?country wdt:P297 ?ciso2 } }
  OPTIONAL { ?c wdt:P131 ?admin1 }
  OPTIONAL { ?c p:P2044/psn:P2044/wikibase:quantityAmount ?elevM }
  OPTIONAL { ?c wdt:P421 ?tz . OPTIONAL { ?tz wdt:P6687 ?tzIana } }
  OPTIONAL { ?article schema:about ?c ; schema:isPartOf <https://en.wikipedia.org/> }
${LABEL_SERVICE}
}
ORDER BY ?c`;
}

function splitCityShard(shard) {
  if (shard.hi === null) {
    // An open top band splits into a bounded band plus a smaller open one.
    const mid = shard.lo * 4;
    if (mid > 50_000_000) return null;
    return [
      { cls: shard.cls, lo: shard.lo, hi: mid },
      { cls: shard.cls, lo: mid, hi: null },
    ];
  }
  const mid = Math.round((shard.lo + shard.hi) / 2);
  if (mid <= shard.lo + 500 || mid >= shard.hi) return null;
  return [
    { cls: shard.cls, lo: shard.lo, hi: mid },
    { cls: shard.cls, lo: mid, hi: shard.hi },
  ];
}

const cityShardName = (shard) =>
  `cities/${shard.cls}-${shard.lo}-${shard.hi === null ? "up" : shard.hi}`;

async function buildCities(countries) {
  log("cities: querying Wikidata by population band");
  const rows = await sparqlSharded(
    CITY_SHARDS,
    cityQuery,
    splitCityShard,
    cityShardName,
    queryOptions,
  );

  const bag = new Map();
  for (const row of rows) {
    const qid = qidOf(v(row, "c"));
    if (!qid) continue;
    let entry = bag.get(qid);
    if (!entry) {
      entry = { qid };
      bag.set(qid, entry);
    }
    const label = v(row, "cLabel");
    push(entry, "name", isPlaceholderLabel(label) ? undefined : label);
    push(entry, "pop", v(row, "pop"));
    push(entry, "coord", v(row, "coord"));
    push(entry, "ciso2", v(row, "ciso2"));
    const country = v(row, "countryLabel");
    if (!isPlaceholderLabel(country)) push(entry, "country", country);
    const admin1 = v(row, "admin1Label");
    if (!isPlaceholderLabel(admin1)) push(entry, "admin1", admin1);
    push(entry, "elevM", v(row, "elevM"));
    const tz = v(row, "tzLabel");
    if (!isPlaceholderLabel(tz)) push(entry, "tzLabel", tz);
    push(entry, "tzIana", v(row, "tzIana"));
    push(entry, "wikipedia", wikipediaTitle(v(row, "article")));
  }

  // Only 7 per cent of settlements carry P421, so a city with no zone of its
  // own inherits its country's, but only when the country has exactly one.
  // That covers Japan, France and most of the world while never guessing for
  // the United States, Russia, Brazil or Australia, where it would be wrong.
  const singleZoneByCountry = new Map();
  for (const country of countries) {
    const zone =
      country.ianaTimeZones.length === 1
        ? country.ianaTimeZones[0]
        : country.timeZones.length === 1
          ? country.timeZones[0]
          : null;
    if (zone) singleZoneByCountry.set(country.iso2, zone);
  }

  const cities = [];
  let inheritedZones = 0;
  for (const entry of bag.values()) {
    const population = maxNumber(entry.pop);
    if (population === undefined || population <= 100_000) continue;
    const name = one(entry.name);
    if (name === undefined) continue;
    const point = parsePoint(one(entry.coord));
    cities.push({
      qid: entry.qid,
      name,
      country_iso2: one(entry.ciso2) ?? null,
      country: one(entry.country) ?? null,
      admin1: one(entry.admin1) ?? null,
      population: Math.round(population),
      lat: point?.lat ?? null,
      lon: point?.lon ?? null,
      elevation_m: round(maxNumber(entry.elevM), 0) ?? null,
      timezone: one(entry.tzIana) ?? one(entry.tzLabel) ?? null,
      wikipedia: one(entry.wikipedia) ?? null,
    });
    const city = cities[cities.length - 1];
    if (city.timezone === null && city.country_iso2 !== null) {
      const inherited = singleZoneByCountry.get(city.country_iso2);
      if (inherited) {
        city.timezone = inherited;
        inheritedZones += 1;
      }
    }
  }
  cities.sort((a, b) => a.qid.localeCompare(b.qid, "en", { numeric: true }));

  const countryRows = countries.map((country) => ({
    iso2: country.iso2,
    iso3: country.iso3 ?? null,
    name: country.name,
    capital: country.capital ?? null,
    continent: country.continent ?? null,
    population: country.population ?? null,
    area_km2: country.areaKm2 ?? null,
    calling_codes: country.callingCodes.join(", ") || null,
    currency_codes:
      country.currencies
        .map((currency) => currency.code)
        .filter(Boolean)
        .join(", ") || null,
    tlds: country.tlds.join(", ") || null,
  }));

  // Duplicate names inside one country: the settlement tree pulls in
  // municipality items alongside their city items, so the same place can
  // appear twice under different qids and slightly different populations.
  const seen = new Map();
  let duplicates = 0;
  for (const city of cities) {
    const key = `${city.country_iso2 ?? "??"}\t${city.name}`;
    if (seen.has(key)) duplicates += 1;
    else seen.set(key, city.qid);
  }

  // A SQLite file has nowhere to put a doc comment, so the caveats live in a
  // table the curated queries can show.
  const metaRows = [
    ["built_at", new Date().toISOString().slice(0, 10)],
    ["license", "CC0 1.0 (Wikidata)"],
    ["source", "https://query.wikidata.org/sparql"],
    ["cities", String(cities.length)],
    ["countries", String(countryRows.length)],
    ["population_threshold", "100000"],
    [
      "note_admin1",
      "admin1 is the immediate P131 parent, so it can be a county, borough or " +
        "metro region rather than a first level division. Chicago reports Cook County.",
    ],
    [
      "note_timezone",
      "Wikidata records a time zone for only a small share of settlements. A city " +
        "with none inherits its country's zone when that country has exactly one, " +
        "so multi zone countries are left null rather than guessed.",
    ],
    [
      "note_duplicates",
      "Some places appear twice, once as the city and once as the municipality " +
        "that contains it. Metropolitan areas such as Greater Tokyo Area are " +
        "included and can outrank cities by population.",
    ],
  ];

  const path = join(publicDataDir, "wikidata-cities.sqlite");
  const engine = await writeCitiesSqlite(path, cities, countryRows, metaRows);

  const bytes = statSync(path).size;
  log(
    `cities: ${cities.length} rows, ${countryRows.length} countries, ${duplicates} duplicate ` +
      `name/country pairs, ${inheritedZones} time zones inherited from the country, ` +
      `${bytes} bytes via ${engine}`,
  );
  if (bytes > 8 * 1024 * 1024) {
    fail(`public/data/wikidata-cities.sqlite is ${bytes} bytes, over the 8 MB budget`);
  }
  return { cities, countryRows, bytes, engine, duplicates };
}

const CITY_DDL = `CREATE TABLE cities (
  qid TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  country_iso2 TEXT,
  country TEXT,
  admin1 TEXT,
  population INTEGER,
  lat REAL,
  lon REAL,
  elevation_m REAL,
  timezone TEXT,
  wikipedia TEXT
);
CREATE TABLE countries (
  iso2 TEXT PRIMARY KEY,
  iso3 TEXT,
  name TEXT NOT NULL,
  capital TEXT,
  continent TEXT,
  population INTEGER,
  area_km2 REAL,
  calling_codes TEXT,
  currency_codes TEXT,
  tlds TEXT
);
CREATE TABLE meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);`;

const CITY_INDEXES = `CREATE INDEX cities_name_idx ON cities (name);
CREATE INDEX cities_country_iso2_idx ON cities (country_iso2);
CREATE INDEX cities_population_idx ON cities (population DESC);
CREATE INDEX countries_name_idx ON countries (name);`;

const CITY_COLUMNS = [
  "qid",
  "name",
  "country_iso2",
  "country",
  "admin1",
  "population",
  "lat",
  "lon",
  "elevation_m",
  "timezone",
  "wikipedia",
];
const COUNTRY_COLUMNS = [
  "iso2",
  "iso3",
  "name",
  "capital",
  "continent",
  "population",
  "area_km2",
  "calling_codes",
  "currency_codes",
  "tlds",
];

/**
 * Builds public/data/wikidata-cities.sqlite.
 *
 * node:sqlite is the preferred path. On Node 22.23 DatabaseSync is available
 * with no flag and only prints an ExperimentalWarning; on a runtime where the
 * module is missing or gated, sql.js (already a dependency, it backs the
 * sqlite-viewer tool) builds the same schema in memory and exports the bytes.
 * Returns which engine was used.
 */
async function writeCitiesSqlite(path, cities, countryRows, metaRows) {
  mkdirSync(publicDataDir, { recursive: true });
  // A PRIMARY KEY conflict on a rebuild is not a useful error message, so the
  // previous file always goes first.
  if (existsSync(path)) rmSync(path);

  // node:sqlite is present and unflagged on Node 22.23 (it only prints an
  // ExperimentalWarning), but it can be missing or gated on other runtimes,
  // so the import failing is a supported path rather than a crash.
  let DatabaseSync;
  try {
    ({ DatabaseSync } = await import("node:sqlite"));
  } catch {
    DatabaseSync = undefined;
  }

  const cityPlaceholders = CITY_COLUMNS.map(() => "?").join(", ");
  const countryPlaceholders = COUNTRY_COLUMNS.map(() => "?").join(", ");
  const cityInsert = `INSERT INTO cities (${CITY_COLUMNS.join(", ")}) VALUES (${cityPlaceholders})`;
  const countryInsert = `INSERT INTO countries (${COUNTRY_COLUMNS.join(", ")}) VALUES (${countryPlaceholders})`;
  const metaInsert = "INSERT INTO meta (key, value) VALUES (?, ?)";

  if (DatabaseSync) {
    const db = new DatabaseSync(path);
    try {
      db.exec("PRAGMA journal_mode = OFF");
      db.exec(CITY_DDL);
      const insertCity = db.prepare(cityInsert);
      const insertCountry = db.prepare(countryInsert);
      const insertMeta = db.prepare(metaInsert);
      db.exec("BEGIN");
      for (const city of cities) insertCity.run(...CITY_COLUMNS.map((key) => city[key]));
      for (const country of countryRows) {
        insertCountry.run(...COUNTRY_COLUMNS.map((key) => country[key]));
      }
      for (const [key, value] of metaRows) insertMeta.run(key, value);
      db.exec("COMMIT");
      db.exec(CITY_INDEXES);
      db.exec("VACUUM");
    } finally {
      db.close();
    }
    return "node:sqlite";
  }

  const { default: initSqlJs } = await import("sql.js");
  const SQL = await initSqlJs({
    locateFile: (file) => join(root, "node_modules", "sql.js", "dist", file),
  });
  const db = new SQL.Database();
  try {
    db.run(CITY_DDL);
    db.run("BEGIN");
    const insertCity = db.prepare(cityInsert);
    for (const city of cities) insertCity.run(CITY_COLUMNS.map((key) => city[key]));
    insertCity.free();
    const insertCountry = db.prepare(countryInsert);
    for (const country of countryRows) {
      insertCountry.run(COUNTRY_COLUMNS.map((key) => country[key]));
    }
    insertCountry.free();
    const insertMeta = db.prepare(metaInsert);
    for (const [key, value] of metaRows) insertMeta.run([key, value]);
    insertMeta.free();
    db.run("COMMIT");
    db.run(CITY_INDEXES);
    db.run("VACUUM");
    writeFileSync(path, Buffer.from(db.export()));
  } finally {
    db.close();
  }
  return "sql.js";
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function ensureIgnore(dir) {
  mkdirSync(dir, { recursive: true });
  const path = join(dir, ".gitignore");
  if (!existsSync(path)) writeFileSync(path, IGNORE_ALL);
}

async function main() {
  const started = Date.now();
  ensureIgnore(generatedDir);
  ensureIgnore(publicDataDir);

  const timings = {};
  const time = async (name, run) => {
    const at = Date.now();
    const value = await run();
    timings[name] = Date.now() - at;
    return value;
  };

  // Cities embeds the country table, so countries is built whenever either is
  // requested. It is one cheap cached query set, so this is not a real cost.
  let countries = null;
  if (wanted.has("countries") || wanted.has("cities")) {
    countries = (await time("countries", buildCountries)).countries;
  }
  if (wanted.has("airports")) await time("airports", buildAirports);
  if (wanted.has("languages")) await time("languages", buildLanguages);
  if (wanted.has("cities")) await time("cities", () => buildCities(countries));

  // Only a full build has asked for every query, so only a full build knows
  // which cache entries are dead. A --only run leaves the cache alone.
  if (only === null) {
    const pruned = pruneCache();
    if (pruned > 0) log(`pruned ${pruned} cache entries left by edited queries`);
  }

  const { requests, networkMs, cacheHits } = stats();
  const parts = Object.entries(timings).map(([name, ms]) => `${name} ${(ms / 1000).toFixed(1)}s`);
  log(
    `done in ${((Date.now() - started) / 1000).toFixed(1)}s ` +
      `(${parts.join(", ")}; ${requests} requests, ${cacheHits} cache hits, ` +
      `${(networkMs / 1000).toFixed(1)}s on the wire)`,
  );
}

main().catch((err) => {
  // A cache miss under --offline is an expected, actionable outcome, so it
  // gets the message and not a stack trace.
  if (err instanceof OfflineCacheMissError) {
    fail(err.message);
    return;
  }
  console.error(err);
  fail(err.message);
});
